#include "include/secure_enclave.h"
int ipop_enclave_init(IPOP_EnclaveContext *ctx, IPOP_SharedMemoryRingBuffer *mem){if(!ctx||!mem)return -1;ctx->ring_buffer=mem;mem->head=0;mem->tail=0;ctx->physical_attestation_verified=0;for(unsigned i=0;i<32;i++)ctx->tee_measurement_hash[i]=0xAA;return 0;}
int ipop_agent_mutate_state(IPOP_EnclaveContext *ctx,uint32_t opcode,const uint8_t *data,uint16_t len,uint64_t ts){if(!ctx||!ctx->ring_buffer||!data||len>IPOP_MAX_MUTATION_PAYLOAD)return -1;uint32_t h=ctx->ring_buffer->head,n=(h+1U)%IPOP_RING_BUFFER_SIZE;if(n==ctx->ring_buffer->tail)return -2;IPOP_StateMutation *m=&ctx->ring_buffer->buffer[h];m->mutation_id=h;m->opcode=opcode;m->timestamp_ns=ts;m->payload_len=len;for(uint16_t i=0;i<len;i++)m->payload[i]=data[i];__sync_synchronize();ctx->ring_buffer->head=n;return 0;}
int ipop_hardware_read_state(IPOP_EnclaveContext *ctx,IPOP_StateMutation *out){if(!ctx||!ctx->ring_buffer||!out)return -1;uint32_t t=ctx->ring_buffer->tail;if(t==ctx->ring_buffer->head)return -2;*out=ctx->ring_buffer->buffer[t];__sync_synchronize();ctx->ring_buffer->tail=(t+1U)%IPOP_RING_BUFFER_SIZE;return 0;}
int ipop_seal_memory_state(const IPOP_EnclaveContext *ctx,uint8_t out[32]){if(!ctx||!ctx->ring_buffer||!out)return -1;ibare_sha256_ctx s;ibare_sha256_init(&s);ibare_sha256_update(&s,ctx->tee_measurement_hash,32);ibare_sha256_update(&s,(const uint8_t*)&ctx->ring_buffer->head,sizeof(ctx->ring_buffer->head));ibare_sha256_update(&s,(const uint8_t*)&ctx->ring_buffer->tail,sizeof(ctx->ring_buffer->tail));for(uint32_t i=0;i<ctx->ring_buffer->head;i++)ibare_sha256_update(&s,(const uint8_t*)&ctx->ring_buffer->buffer[i],sizeof(IPOP_StateMutation));ibare_sha256_final(&s,out);return 0;}
